import VCard from './index.js';
const limits={name:50,org:80,title:80,phone:32,email:100,note:300};
function wellFormed(s){for(let i=0;i<s.length;i++){const c=s.charCodeAt(i);if(c>=0xd800&&c<=0xdbff){const d=s.charCodeAt(++i);if(!(d>=0xdc00&&d<=0xdfff))return false;}else if(c>=0xdc00&&c<=0xdfff)return false;}return true;}
self.onmessage=({data})=>{try{if(!data||typeof data!=='object'||Object.keys(data).sort().join(',')!==Object.keys(limits).sort().join(','))throw Error('仅允许单张联系卡的六个固定字段。');for(const[k,max]of Object.entries(limits)){const v=data[k];if(typeof v!=='string'||v.length>max||!wellFormed(v)||(/[\x00-\x1f\x7f-\x9f\u2028\u2029]/.test(k==='note'?v.replace(/\n/g,''):v)))throw Error('字段超长或含不允许的换行/控制字符，未生成。');}if(!data.name.trim())throw Error('请填写自己的姓名。');if(Object.values(data).join('').length>2048||new TextEncoder().encode(Object.values(data).join('')).length>8192)throw Error('总文字超过2048字符或8KiB。');if(data.phone&&(!/^\+?[0-9 ()-]+$/.test(data.phone)||!/^\d{3,20}$/.test(data.phone.replace(/\D/g,''))))throw Error('电话只支持3–20个数字及有限+空格括号横线，不验证可接通。');if(data.email&&!/^[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)+$/.test(data.email))throw Error('邮箱只支持常见ASCII地址，不查询是否存在。');const generatedAt=new Date().toISOString(),card=new VCard();card.addFullName(data.name).addName({givenName:data.name});if(data.org)card.addCompany({name:data.org});if(data.title)card.addJobtitle(data.title);if(data.phone)card.addPhoneNumber({number:data.phone,type:['cell']});if(data.email)card.addEmail({address:data.email,type:['work']});if(data.note)card.addNote(data.note);card.addRevision(new Date(generatedAt));const vcf=card.buildVCard(),result={schema:1,library:'vcard-creator1.0.0',generatedAt,fields:data,notice:'自己的单张VCF3联系卡；不会自动导入/发送/拨号。未自动拆分姓和名；手机排序/导入可能不同，电话号码邮箱未验证。'};if(new TextEncoder().encode(vcf).length>16384||new TextEncoder().encode(JSON.stringify(result)).length>16384)throw Error('输出超过16KiB。');postMessage({ok:true,vcf,result});}catch(e){postMessage({ok:false,error:e.message||'本机联系卡处理失败，请重试。'});}};
